    Where-Object { $_.FullName -notmatch '\\(build|\.dart_tool|\.idea|ephemeral)\\' } |
    ForEach-Object { "{0,6}  {1}" -f ([System.IO.File]::ReadAllLines($_.FullName).Count), ($_.FullName.Substring($p.Length+1)) }
