  Get-ChildItem -LiteralPath $p -Recurse -File -Force -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\(build|\.dart_tool|\.idea|ephemeral)\\' -and $_.Extension -match '^\.(dart|php|sql|yaml|yml|json|md|txt|lock|html|css|js|xml|iml|properties)$' } |
    Select-String -Pattern 'PhpSpreadsheet|Spreadsheet|[Xx]lsx|Excel|phpoffice' -ErrorAction SilentlyContinue
}
