}

Write-Output ""
Write-Output "===== 5. .xlsx files on disk in both trees ====="
foreach ($p in @($A,$B)) { Get-ChildItem -LiteralPath $p -Recurse -File -Force -Include *.xlsx,*.xls -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName } }
